/bin/bash -lc "python - <<'PY'
import requests
for repo in ['pydeseq2','bioconductor-deseq2','deseq2']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=10'
    try:
        r=requests.get(url, timeout=15)
        print(repo, r.status_code)
        if r.ok:
            data=r.json()
            tags=[t['name'] for t in data.get('tags', [])[:10]]
            print(tags)
        else:
            print(r.text[:120])
    except Exception as e:
        print(repo, type(e).__name__, e)
PY"

